<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0f766e"><meta name="description" content="CRM Camp Resident MUTU"><link rel="manifest" href="/manifest.webmanifest"><link rel="apple-touch-icon" href="/icons/icon-192.png"><title>CRM Camp Resident MUTU</title><style>:root{font-family:Inter,system-ui,sans-serif;color:#172033;background:#f5f7fb}body{margin:0}.wrap{max-width:1180px;margin:auto;padding:1rem 1.25rem}.top{display:flex;justify-content:space-between;align-items:center;gap:1rem}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1rem}.card{background:#fff;border-radius:16px;padding:1.1rem;box-shadow:0 4px 18px #17203312}.muted{color:#64748b}.btn{background:#0f766e;color:white;border:0;border-radius:9px;padding:.65rem 1rem}.install{display:none}@media(max-width:600px){h1{font-size:1.35rem}.top{align-items:flex-start;flex-direction:column}}@media(prefers-color-scheme:dark){:root{color:#e5e7eb;background:#111827}.card{background:#1f2937}.muted{color:#9ca3af}}</style></head><body><main class="wrap"><header class="top"><div><h1>CRM Camp Resident MUTU</h1><p class="muted">Dashboard operasional harian</p></div><button id="install" class="btn install">Install aplikasi</button></header><section id="stats" class="grid" style="margin-top:1rem"><div class="card">Memuat data…</div></section><section class="card" style="margin-top:1rem"><h2>Booking terbaru</h2><div id="bookings">Login diperlukan untuk melihat data.</div></section></main><script>let deferred;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;install.style.display='block'});install?.addEventListener('click',async()=>{if(deferred){deferred.prompt();await deferred.userChoice;deferred=null;install.style.display='none'}});async function load(){const r=await fetch('/api/v1/dashboard',{headers:{Accept:'application/json'}});if(!r.ok)return;const d=await r.json();stats.innerHTML=[['Booking hari ini',d.bookings_today],['Tamu aktif',d.active_guests],['Kamar tersedia',d.available_rooms],['Menunggu konfirmasi',d.pending_bookings]].map(x=>`<div class="card"><div class="muted">${x[0]}</div><h2>${x[1]}</h2></div>`).join('');bookings.innerHTML=d.recent_bookings.map(b=>`<p><b>${b.booking_code}</b> — ${b.guest.name} (${b.status})</p>`).join('')||'Belum ada booking.'}load();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');</script></body></html>